repo_files.version.py:
"""API version header extractor."""

from typing import Dict


class APIVersionExtractor:
    @staticmethod
    def extract_version(headers: Dict[str, str]) -> str:
        # Header: X-API-Version: 2026-01 or Accept: application/vnd.app.v2+json
        v_hdr = headers.get("X-API-Version")
        if v_hdr:
            return v_hdr.strip()
        accept = headers.get("Accept", "")
        if "vnd.app.v2" in accept:
            return "v2"
        return "v1"

repo_files.adapter_v1.py:
"""V1 API payload adapter."""

from typing import Any, Dict


class V1Adapter:
    @staticmethod
    def format_response(user_id: str, name: str) -> Dict[str, Any]:
        return {"id": user_id, "name": name, "version": "v1"}

repo_files.adapter_v2.py:
"""V2 API payload adapter."""

from typing import Any, Dict


class V2Adapter:
    @staticmethod
    def format_response(user_id: str, name: str) -> Dict[str, Any]:
        return {"data": {"userId": user_id, "displayName": name}, "version": "v2"}

repo_files.router.py:
"""Versioned route dispatcher."""

from typing import Any, Dict
from adapter_v1 import V1Adapter
from adapter_v2 import V2Adapter
from version import APIVersionExtractor


class VersionedAPIRouter:
    def route_request(self, headers: Dict[str, str], user_id: str, name: str) -> Dict[str, Any]:
        ver = APIVersionExtractor.extract_version(headers)
        # BUG: Case-sensitive version equality check fails on "V2" or date strings like "2026-01"!
        if ver == "v2":
            return V2Adapter.format_response(user_id, name)
        return V1Adapter.format_response(user_id, name)

reference_fix.router.py:
"""Versioned route dispatcher."""

from typing import Any, Dict
from adapter_v1 import V1Adapter
from adapter_v2 import V2Adapter
from version import APIVersionExtractor


class VersionedAPIRouter:
    def route_request(self, headers: Dict[str, str], user_id: str, name: str) -> Dict[str, Any]:
        ver = APIVersionExtractor.extract_version(headers).lower()
        if ver in ("v2", "2026-01", "2"):
            return V2Adapter.format_response(user_id, name)
        return V1Adapter.format_response(user_id, name)
